window.lucidShortcut=async label=>{const m={Explain:'Explain the selected/current concept.',Simplify:'Simplify the selected/current concept.',Analogy:'Give an analogy for this concept.',Example:'Give a real-world example.',Connect:'Connect this to the previous topic.',Summarize:'Summarize the current page or section.',Flashcards:'Create five flashcards.',Socratic:'Ask me three Socratic questions.',Quiz:'Generate five quiz questions.',Revision:'Create a revision plan.',Teach:'Teach this as a compact mini-lesson.',Mistakes:'Analyze recent mistakes and suggest a review.'};$('lucidAIQ').value=m[label]||label;await askLucidAI()};
window.askLucidAI=async()=>{if(!auth()){toast('Sign in to use Lucid AI.');return}const qx=$('lucidAIQ')?.value.trim();if(!qx)return;const a=$('lucidAIA');a.textContent='Thinking with your learning context…';try{const r=await ai('summarize',qx,{selectedText:window.getSelection?.()?.toString()?.trim()||''});const t=r.text||r.summary||r.lesson||JSON.stringify(r,null,2);a.innerHTML=esc(t).replace(/\n/g,'<br>');await track('ai_question_asked',{question:qx})}catch(e){a.innerHTML='<span class="lucid-chip red">'+esc(e.message)+'</span>'}};

renderers.settings=async()=>{
 const p=ensurePage('settings','Settings','Privacy · AI · notifications · accessibility'),c=$('settingsContent');c.innerHTML='<div class="lucid-grid lucid-cols-2"><div class="lucid-card"><h3>AI coaching mode</h3><p class="lucid-muted">Gentle, energetic, direct, academic or casual.</p><select id="lCoach" style="margin-top:8px"><option>gentle</option><option>energetic</option><option>direct</option><option>academic</option><option>casual</option></select><button class="lucid-btn primary" onclick="saveLucidPrefs()" style="margin-top:8px">Save</button></div><div class="lucid-card"><h3>Privacy</h3><div class="lucid-stack"><label><input type="checkbox" id="vLevel" checked> Level / XP public</label><label><input type="checkbox" id="vStreak" checked> Streak public</label><label><input type="checkbox" id="vSubject" checked> Subject levels public</label><label><input type="checkbox" id="vBadges" checked> Badges public</label><small class="lucid-muted">Exact study material and private AI chats remain private by default.</small></div></div><div class="lucid-card"><h3>Notifications</h3><p class="lucid-muted">Resume, review, room, milestone, improvement and recovery prompts are stored sparsely.</p><button class="lucid-btn" onclick="enableLucidNotifications()" style="margin-top:8px">Enable browser notifications</button></div><div class="lucid-card"><h3>Continuity</h3><p class="lucid-muted">Local PDFs are available offline. Persistent learning state syncs after sign-in.</p><label><input type="checkbox" id="lReduce" onchange="localStorage.setItem(\'lucid-reduced-motion\',this.checked?\'1\':\'0\')"> Reduced motion</label></div></div>';
 if(auth()){const {data}=await SB().from('profiles').select('coaching_mode,visibility').eq('id',uid()).maybeSingle();if(data){$('lCoach').value=data.coaching_mode||'gentle';const v=data.visibility||{};$('vLevel').checked=v.level_xp!==false;$('vStreak').checked=v.streak!==false;$('vSubject').checked=v.subject_levels!==false;$('vBadges').checked=v.badges!==false}}}
