window.saveLucidPrefs=async()=>{if(!auth())return;const visibility={level_xp:$('vLevel').checked,streak:$('vStreak').checked,subject_levels:$('vSubject').checked,badges:$('vBadges').checked,aggregate_stats:true,exact_location:false};await SB().from('profiles').update({coaching_mode:$('lCoach').value,visibility}).eq('id',uid());toast('Preferences saved ✓')};
